module TopModule (
    input  [7:0] a,
    input  [7:0] b,
    output [7:0] s,
    output       overflow
);

    // Internal signal for the 9-bit sum (to capture the carry out of bit 7)
    wire [8:0] sum;

    // Perform the addition. The extra MSB captures the carry out of bit 7.
    assign sum = {1'b0, a} + {1'b0, b};

    // The 8-bit result is the lower 8 bits of the sum.
    assign s = sum[7:0];

    // Overflow detection for two's complement addition:
    // Overflow occurs if the carry into the MSB (bit 7) differs from the carry out of the MSB.
    // Here, sum[8] is the carry out of bit 7, and sum[7] is the result bit 7.
    // The carry into bit 7 is implicitly the previous carry, but we can determine overflow
    // by comparing the carry into and out of the sign bit.
    // A standard way: overflow = (carry into MSB) XOR (carry out of MSB).
    // Since we added two 8-bit numbers with an implicit 0 MSB extension,
    // the carry into bit 7 is sum[7] before the final addition step, 
    // but simpler: overflow occurs if the carry into bit 7 differs from carry out.
    // Using the property: for a+b, overflow = (a[7] & b[7] & ~sum[7]) | (~a[7] & ~b[7] & sum[7])
    // However, using the carry bits from the adder is more direct.
    // The carry into bit 7 is actually the carry out of bit 6. 
    // To get that, we would need a chain of adders or use a different approach.
    // 
    // Alternative: Since we have sum[8] (carry out of bit 7) and we know the inputs,
    // we can compute overflow by checking the signs.
    // Overflow in signed addition: result has opposite sign to both inputs, 
    // or same sign to one and different to other in a specific way.
    // The most robust synthesizable way using the available signals:
    // We can infer the carry into bit 7 by looking at the addition of the lower bits, 
    // but that is complex.
    //
    // Let's use the standard definition: 
    // Overflow = CarryIn_MSB XOR CarryOut_MSB.
    // To get CarryIn_MSB, we can note that if we add a and b, 
    // the carry into bit 7 is the carry out of bit 6.
    // Since we cannot easily extract carry out of bit 6 from a single adder 
    // without additional logic or a different structure, 
    // we can compute overflow based on the signs of a, b, and s.
    //
    // Rule: Overflow occurs if (a[7] == b[7]) AND (a[7] != s[7]).
    // This checks if both inputs had the same sign, but the result has the opposite sign.
    //
    // Let's verify this rule.
    // If a and b are both positive (MSB=0), sum should be positive. If sum[7]=1, overflow.
    // If a and b are both negative (MSB=1), sum should be negative. If sum[7]=0, overflow.
    // If a and b have different signs, overflow cannot occur (sum is within range).
    //
    // This is the standard, most efficient way to check overflow without 
    // tracking internal carries explicitly across the whole width, 
    // relying only on the MSBs and the result MSB.
    //
    // However, the prompt asks to "compute whether a (signed) overflow has occurred".
    // Using the sign bits is the correct synthesis approach.
    //
    // Let's double check the XOR of carry in/out.
    // Carry out of bit 7 is sum[8] (from our assignment sum = {1'b0, a} + {1'b0, b}).
    // Carry into bit 7 is the carry out of bit 6. Let's call it C6.
    // We don't have C6 directly.
    // But we can derive overflow as: (a[7] & b[7] & ~s[7]) | (~a[7] & ~b[7] & s[7]).
    // This is equivalent to: (a[7] == b[7]) && (a[7] != s[7]).

    // Implementation using the sign comparison method.
    // This is fully synthesizable and standard for 2's complement adders.

    assign overflow = (a[7] & b[7] & ~s[7]) | (~a[7] & ~b[7] & s[7]);

endmodule

