module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic s,
    input  logic w,
    output logic z
);

    // State encoding: 2 bits are sufficient (A=00, B=01)
    typedef enum logic [1:0] {
        A = 2'b00,
        B = 2'b01
    } state_t;

    state_t state, next_state;

    // State register (synchronous reset, active high)
    always_ff @(posedge clk) begin
        if (reset)
            state <= A;
        else
            state <= next_state;
    end

    // Next-state logic
    always_comb begin
        // Default: stay in current state
        next_state = state;

        case (state)
            A: begin
                // Stay in A as long as s = 0; move to B when s = 1
                if (s == 1'b1)
                    next_state = B;
                // else remain in A
            end

            B: begin
                // From B, transition back to A unconditionally.
                // The problem states the FSM "continues checking w for the
                // next three clock cycles, and so on", which is interpreted
                // as: after each 3‑cycle window the FSM returns to A to
                // start a new window.
                next_state = A;
            end

            default: next_state = A;
        endcase
    end

    // Output logic
    // z is asserted high in the clock cycle immediately after a window
    // of three consecutive cycles in which w = 1 in exactly two of those
    // cycles.  We keep a 3‑bit shift register that captures the last
    // three w values (including the current cycle).  When the register
    // contains exactly two 1's we set z for the next cycle.
    logic [2:0] w_shift;   // w_shift[0] = latest w, w_shift[2] = oldest

    // Shift the w value on every positive edge (except when reset)
    always_ff @(posedge clk) begin
        if (reset)
            w_shift <= 3'b000;
        else
            w_shift <= {w, w_shift[2:1]};
    end

    // Combinational assignment for z:
    // z = 1 in the cycle after we detect exactly two 1's in the shift register.
    // Because the shift register is updated on the clock edge, the detection
    // uses the value present at the beginning of the current cycle, and
    // the resulting z becomes valid in the following cycle.
    assign z = (w_shift == 3'b011) || (w_shift == 3'b101) || (w_shift == 3'b110);

