    // 2'b00: IDLE (waiting for reset release)
    // 2'b01: ACCEPTING (collecting bits, LSB first)
    // 2'b10: COMPLEMENTING (processing remaining bits and final carry)
    // 2'b11: DONE (output stable, waiting for next reset)
    reg [1:0] state, next_state;

    // Internal registers
    // accum holds the accumulated value (LSB first)
    // bit_count tracks how many bits have been processed
    reg [7:0] accum;   // 8-bit accumulator (sufficient for demonstration; can be widened)
    reg [3:0] bit_count; // 4-bit counter (0-15)

    // Output assignment: z is the MSB of the accumulator (2's complement MSB)
    assign z = accum[7];

    // State register (positive edge triggered, asynchronous active-high reset)
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= 2'b00; // IDLE
            accum <= 8'b0;
            bit_count <= 4'b0;
        end else begin
            state <= next_state;
        end
    end

    // Next-state logic (combinational)
    always @(*) begin
        case (state)
            2'b00: begin // IDLE
                // Wait for reset release
                if (areset == 1'b0) begin
                    next_state = 2'b01; // Transition to ACCEPTING
                end else begin
                    next_state = 2'b00; // Stay in IDLE
                end
            end

            2'b01: begin // ACCEPTING
                // Process one bit per clock cycle
                // Shift in the new LSB (x) into accumulator
                // accum = {accum[6:0], x} effectively multiplies by 2 and adds x
                // But we need to keep the full width; we shift left and add x at LSB
                // Actually, since x is LSB first, we accumulate: accum = accum * 2 + x
                // Using 8-bit accumulator, we shift left and add x
                next_state = 2'b01; // Stay in ACCEPTING
                // Note: The actual accumulation is done in the sequential block below
            end

            2'b10: begin // COMPLEMENTING
                // After all bits are entered (we stop when reset is asserted),
                // we need to compute 2's complement: flip bits and add 1.
                // Since we process bits LSB first, the accumulated value is the original number.
                // 2's complement = ~accum + 1
                // We can implement this by inverting and propagating carry.
                // For simplicity, we just invert the accumulator and set carry for add 1.
                // The output z is the MSB of the complemented value.
                next_state = 2'b11; // Go to DONE after one cycle
