    // State register (positive edge triggered, async reset)
    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= 2'b00;  // walk_left
        else
            state <= next_state;
    end

    // Next-state logic (combinational)
    always @(*) begin
        // Default: keep current state
        next_state = state;

        case (state)
            2'b00: begin // WALKING_LEFT
                if (!ground) begin
                    // Fall has higher precedence than dig or direction switch
                    next_state = 2'b10; // FALLING
                end else if (dig && !bump_left && !bump_right) begin
                    // Dig when walking on ground, no bump
                    next_state = 2'b11; // DIGGING
                end else if (bump_left || bump_right) begin
                    // Switch direction when bumped (both sides switch to right)
                    next_state = 2'b01; // WALKING_RIGHT
                end
                // else: stay walking left
            end

            2'b01: begin // WALKING_RIGHT
                if (!ground) begin
                    next_state = 2'b10; // FALLING
                end else if (dig && !bump_left && !bump_right) begin
                    next_state = 2'b11; // DIGGING
                end else if (bump_left || bump_right) begin
                    next_state = 2'b00; // WALKING_LEFT
                end
                // else: stay walking right
            end

            2'b10: begin // FALLING
                if (ground) begin
                    // Ground reappears: resume walking in same direction as before fall
                    // We need to remember the direction before falling.
                    // Since we only have state, we infer the direction from the
                    // previous state. But here we are in FALLING.
                    // The specification: "resume walking in the same direction
                    // as before the fall".
                    // We must track the direction. We can use the fact that
                    // if it was walking left before, it resumes left.
                    // However, we don't have a separate register for direction.
                    // We need to store the walking direction during fall.
                    // Let's re-examine: we can use the state encoding to also
                    // store the direction. But we have only 2 bits.
                    // We can change encoding or use additional logic.
                    // Actually, we can deduce: if it was walking left (00) and fell,
