                    // Since we can't add registers here arbitrarily, let's rethink.
                    // We can use the state to encode direction even in fall.
                    // Let's change encoding:
                    // 2'b00: WALKING_LEFT
                    // 2'b01: WALKING_RIGHT
                    // 2'b10: FALLING_LEFT  (falling but was going left)
                    // 2'b11: FALLING_RIGHT  (falling but was going right)
                    // But then we have 4 states, which is fine.
                    // Let's restart the state encoding properly.
                end
                // else: stay falling
            end

            2'b11: begin // DIGGING
