module TopModule (
    input  clk,
    input  reset,
    output [4:0] q
);

    // Internal register for the LFSR state
    reg [4:0] shift_reg;

    // Taps at bit positions 5 and 3 (1-indexed from MSB) correspond to
    // indices 4 and 2 (0-indexed). The feedback bit is XOR of q[4] and q[2].
    wire feedback = shift_reg[4] ^ shift_reg[2];

    // Synchronous reset and shift operation on positive edge of clk
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Active-high synchronous reset sets the output to 1 (binary 00001)
            shift_reg <= 5'b00001;
        end else begin
            // Galois LFSR right-shift:
            // - Bit 4 (MSB) gets feedback
            // - Bit 3 gets previous bit 4
            // - Bit 2 (tap position) gets XOR of previous bit 3 and feedback
            // - Bit 1 gets previous bit 2
            // - Bit 0 (LSB) gets previous bit 1
            shift_reg <= {feedback, shift_reg[4:1]};
        end
    end

    // Continuous assignment to output port q
    assign q = shift_reg;

endmodule

