module TopModule (
    input  clk,
    input  reset,
    input  in,
    output done
);

    // State encoding: 4 bits are sufficient for the 7 defined states
    typedef enum logic [3:0] {
        IDLE      = 4'b0000,  // Waiting for start bit
        START     = 4'b0001,  // Detected start bit, sampling data bits
        DATA0     = 4'b0010,  // Receiving data bit 0 (LSB)
        DATA1     = 4'b0011,  // Receiving data bit 1
        DATA2     = 4'b0100,  // Receiving data bit 2
        DATA3     = 4'b0101,  // Receiving data bit 3
        DATA4     = 4'b0110,  // Receiving data bit 4
        DATA5     = 4'b0111,  // Receiving data bit 5
        DATA6     = 4'b1000,  // Receiving data bit 6
        DATA7     = 4'b1001,  // Receiving data bit 7 (MSB)
        STOP      = 4'b1010,  // Verifying stop bit
        ERROR     = 4'b1011   // Stop bit mismatch; wait for next start
    } state_t;

    // State register and next-state logic
    state_t state, next_state;

    // Counter for bit indexing (0 to 7 for 8 data bits)
    // Also used to track stop bit position
    logic [3:0] bit_cnt;
    logic [3:0] next_bit_cnt;

    // Output register for the 'done' signal
    logic done_reg, next_done;

    // -------------------------------------------------------
    // Next-state and output logic (combinational)
    // -------------------------------------------------------

    always_comb begin
        next_state   = state;
        next_bit_cnt = bit_cnt;
        next_done    = 1'b0;

        case (state)
            IDLE: begin
                // Idle until a falling edge (start bit) is detected
                if (~in) begin
                    next_state = START;
                    next_bit_cnt = 4'b0000; // Will be incremented on first data sample
                end
            end

            START: begin
                // After sampling one clock cycle of the start bit (level low),
                // transition to data bit 0 sampling.
                // We assume the start bit duration is one clock cycle for simplicity.
                next_state = DATA0;
                next_bit_cnt = 4'b0001; // point to next bit (bit 0 sampled, move to 1)
            end

            // ----- Data bit reception states -----
            // The FSM samples the data line on every positive clock edge.
            // bit_cnt tracks which data bit (0-7) is currently being received.
            DATA0: begin
                // Sample bit 0 (LSB). Always accept the value on in.
                next_state = DATA1;
                next_bit_cnt = 4'b0010; // point to next bit
            end

            DATA1: begin
                next_state = DATA2;
                next_bit_cnt = 4'b0100;
            end

            DATA2: begin
                next_state = DATA3;
                next_bit_cnt = 4'b0110;
            end

            DATA3: begin
                next_state = DATA4;
                next_bit_cnt = 4'b1000;
            end

            DATA4: begin
                next_state = DATA5;
                next_bit_cnt = 4'b1010;
            end

            DATA5: begin
                next_state = DATA6;
                next_bit_cnt = 4'b1100;
            end

            DATA6: begin
                next_state = DATA7;
                next_bit_cnt = 4'b1110;
            end

            DATA7: begin
                // After receiving the 8th bit (MSB), move to stop bit verification.
                next_state = STOP;
                next_bit_cnt = 4'b0000; // reuse counter for stop bit position check
            end

            // ----- Stop bit verification -----
            STOP: begin
                // The stop bit should be logic 1.
                if (in) begin
                    // Correct stop bit: signal 'done' and return to IDLE.
                    next_done = 1'b1;
                    next_state = IDLE;
                end else begin
                    // Stop bit was 0 -> error.
                    // Wait here until a start bit (falling edge) appears.
                    // Remain in STOP state; next_state stays STOP.
                    // We do not advance bit_cnt; just keep checking 'in'.
                    next_state = STOP;
                end
            end

            // ----- Error state -----
            // If at any point the protocol is violated (e.g., start bit not found),
            // we transition to ERROR and wait for a new start bit.
            // For this simple implementation, ERROR is entered if we ever
            // detect an unexpected condition; however, the STOP state already
            // handles the stop-bit-mismatch case by looping.
            ERROR: begin
                if (~in) begin
                    next_state = START;
                end else begin
                    next_state = ERROR;
                end
            end

            default: next_state = IDLE;
        endcase
    end

    // -------------------------------------------------------
    // State register (positive-edge-triggered, async reset)
    // -------------------------------------------------------

    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            state      <= IDLE;
            bit_cnt    <= 4'b0000;
            done_reg   <= 1'b0;
        end else begin
            state      <= next_state;
            bit_cnt    <= next_bit_cnt;
            done_reg   <= next_done;
        end
    end

    // -------------------------------------------------------
    // Output assignment
    // -------------------------------------------------------

    assign done = done_reg;

endmodule

