module TopModule (
    input  [254:0] in,
    output [7:0]   out
);

    // Internal signals for the carry-save adder tree.
    // Each row is 9 bits wide (0..8) to safely accommodate intermediate sums.
    wire [8:0] row1;
    wire [8:0] row2;
    wire [8:0] row3;
    wire [8:0] row4;
    wire [8:0] row5;
    wire [8:0] row6;
    wire [8:0] row7;

    // Stage 1: Group bits into pairs and sum them.
    // row1 has ceil(255/2) = 128 entries (indices 0 to 127).
    genvar i;
    generate
        for (i = 0; i < 255; i = i + 2) begin : pair_sum
            // If i+1 exists, add the two bits; otherwise use the single bit.
            // The result is placed in row1[i/2].
            assign row1[i/2] = (i + 1 < 255) ? (in[i] + in[i+1]) : in[i];
        end
    endgenerate

    // Stage 2: Sum pairs of row1 results (groups of 4 bits -> 3 bits).
    // row1 has 128 entries; row2 will have 64 entries (indices 0 to 63).
    generate
        for (i = 0; i < 128; i = i + 2) begin : pair_sum2
            // row1 indices go up to 127. If i+1 < 128, add them.
            assign row2[i/2] = (i + 1 < 128) ? (row1[i] + row1[i+1]) : row1[i];
        end
    endgenerate

    // Stage 3: Sum pairs of row2 results (groups of 8 bits -> 4 bits).
    // row2 has 64 entries; row3 will have 32 entries (indices 0 to 31).
    generate
        for (i = 0; i < 64; i = i + 2) begin : pair_sum3
            assign row3[i/2] = (i + 1 < 32) ? (row2[i] + row2[i+1]) : row2[i];
        end
    endgenerate

    // Stage 4: Sum pairs of row3 results (groups of 16 bits -> 5 bits).
    // row3 has 32 entries; row4 will have 16 entries (indices 0 to 15).
    generate
        for (i = 0; i < 32; i = i + 2) begin : pair_sum4
            assign row4[i/2] = (i + 1 < 16) ? (row3[i] + row3[i+1]) : row3[i];
        end
    endgenerate

    // Stage 5: Sum pairs of row4 results (groups of 32 bits -> 6 bits).
    // row4 has 16 entries; row5 will have 8 entries (indices 0 to 7).
    generate
        for (i = 0; i < 16; i = i + 2) begin : pair_sum5
            assign row5[i/2] = (i + 1 < 8) ? (row4[i] + row4[i+1]) : row4[i];
        end
    endgenerate

    // Stage 6: Sum pairs of row5 results (groups of 64 bits -> 7 bits).
    // row5 has 8 entries; row6 will have 4 entries (indices 0 to 3).
    generate
        for (i = 0; i < 8; i = i + 2) begin : pair_sum6
            assign row6[i/2] = (i + 1 < 4) ? (row5[i] + row5[i+1]) : row5[i];
        end
    endgenerate

    // Stage 7: Combine the 4 remaining counts (row6[0..3]) into the final 8-bit result.
    // row6 has 4 entries (indices 0 to 3). We add them in two stages.
    wire [8:0] sum12;
    wire [8:0] sum34;
    wire [8:0] final_sum;

    // Adder for first pair: row6[0] + row6[1]
    assign sum12 = row6[0] + row6[1];
    // Adder for second pair: row6[2] + row6[3]
    assign sum34 = row6[2] + row6[3];
    // Final adder
    assign final_sum = sum12 + sum34;

    // The result is the lower 8 bits. The 9th bit (index 8) is discarded;
    // the maximum possible count is 255, which fits in 8 bits.
    assign out = final_sum[7:0];

endmodule

