                    state <= 2'b11; // S2 -> S3
                else
                    state <= 2'b01; // S2 -> S1
            end
            2'b11: begin
                if (a)
                    state <= 2'b10; // S3 -> S2
                else
                    state <= 2'b00; // S3 -> S0
            end
