Prob144_conwaylife.code:
module TopModule (
    input  clk,
    input  load,
    input  [255:0] data,
    output reg [255:0] q
);

    // Internal register to hold the current state
    reg [255:0] state;

    // Helper function to compute the number of alive neighbours for a cell
    // given its row and column (0..15). The grid is a toroid.
    function [3:0] count_neighbours;
        input [3:0] r, c;
        integer i, j;
        integer nr, nc;
        integer count;
        begin
            count = 0;
            for (i = 0; i < 3; i = i + 1) begin
                for (j = 0; j < 3; j = j + 1) begin
                    // Skip the cell itself (dr=0, dc=0)
                    if (i == 1 && j == 1) begin
                        continue;
                    end
                    // Compute wrapped row and column
                    nr = r + i - 1;
                    nc = c + j - 1;
                    if (nr < 0) nr = nr + 16;
                    if (nr >= 16) nr = nr - 16;
                    if (nc < 0) nc = nc + 16;
                    if (nc >= 16) nc = nc - 16;
                    // Add the state of the neighbour
                    count = count + state[nr * 16 + nc];
                end
            end
            count_neighbours = count[3:0]; // truncated to 4 bits (max 8)
        end
    endfunction

    // Combinational logic: compute next state
    wire [255:0] next_state;
    integer r, c;
    integer neighbours;

    generate
        // Unroll the 16x16 grid
        for (r = 0; r < 16; r = r + 1) begin: row_gen
            for (c = 0; c < 16; c = c + 1) begin: col_gen
                // Compute neighbour count for this cell
                neighbours = count_neighbours(r, c);

                // Apply Game of Life rules
                // (1) 0-1 neighbour -> 0
                // (2) 2 neighbours   -> stay same
                // (3) 3 neighbours   -> 1
                // (4) 4+ neighbours  -> 0
                assign next_state[r * 16 + c] = 
                    (neighbours == 3) ? 1'b1 :
                    (neighbours == 2) ? state[r * 16 + c] :
                    1'b0;
            end
        end
    endgenerate

    // Sequential logic: load or advance
    always @(posedge clk) begin
        if (load) begin
            // Load initial state
            q <= data;
            state <= data;
        end else begin
            // Advance one timestep
            q <= next_state;
            state <= next_state;
        end
    end

endmodule

Prob153_gshare.code:
module TopModule (
    input  clk,
    input  areset,
    input  predict_valid,
    input  [6:0] predict_pc,
    output predict_taken,
    output [6:0] predict_history,
    input  train_valid,
    input  train_taken,
    input  train_mispredicted,
    input  [6:0] train_history,
    input  [6:0] train_pc
);

    // 7-bit global history register
    reg [6:0] ghistory;
    // 128-entry PHT (7-bit index)
    reg [1:0] pht [0:127];

    // Internal signals for prediction
    wire [6:0] pht_index;
    wire [1:0] pht_value;
    wire taken_prediction;

    // Assign index: XOR of PC and global history
    assign pht_index = predict_pc ^ ghistory;

    // PHT read
    assign pht_value = pht[pht_index];

    // Prediction logic: taken if counter >= 2
    assign taken_prediction = (pht_value >= 2'b10);
    assign predict_taken = taken_prediction;
    assign predict_history = ghistory;

    // Training logic
    // When train_valid is active, update PHT and potentially history
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            ghistory <= 7'b0;
            // Initialize PHT optionally, here left as is
        end else begin
            // Priority: training over prediction for history update
            if (train_valid) begin
                // Update PHT for the trained PC history
                // Index calculation for training
                wire [6:0] train_idx = train_pc ^ train_history;
                pht[train_idx] <= train_taken ? (pht[train_idx] + 1'b1) : (pht[train_idx] - 1'b1);

                // If mispredicted, recover history to state after mispredicting branch
                // This implies resetting history or setting to a specific state.
                // Given the spec: "recover the branch history register to the state 
                // immediately after the mispredicting branch completes execution."
                // We assume this means setting history to the train_history value 
                // or a reset state. Here we set it to train_history as the known state.
                if (train_mispredicted) begin
                    ghistory <= train_history;
                end
            end else begin
                // Prediction path: update history at next clock edge for the predicted branch
                if (predict_valid) begin
                    // Update history: shift in the predicted taken outcome
                    // The predicted taken is taken_prediction
                    // Standard ghistory update: (ghistory << 1) | taken_prediction
                    ghistory <= {ghistory[5:0], taken_prediction};
                end
            end
        end
    end

endmodule
